def add_orta(S, ENGLISH_ROLES, TWISTS):
    def scene(id, code, level, emoji, name, title, role, en_role, twists, situation, opening, goals, phrases):
        S(id, code, level, emoji, name, title, role, situation, opening, goals, phrases, minutes=6)
        ENGLISH_ROLES[id] = en_role
        TWISTS[id] = twists

